package com.rootmyandroid.rootz

/**
 * SPAKE2 (BoringSSL ed25519 flavor) fixed-point precomputation tables,
 * extracted verbatim from BoringSSL crypto/curve25519/spake25519.cc
 * (kSpakeMSmallPrecomp / kSpakeNSmallPrecomp, 15 * 2 * 32 = 960 bytes each).
 * M is the mask point for the CLIENT (alice); N for the SERVER (bob).
 * These are public, fixed constants of the protocol, not secrets.
 */
internal object SpakeTables {

    internal val M_PRECOMP: ByteArray = hexToBytes(M_PRECOMP_HEX)
    internal val N_PRECOMP: ByteArray = hexToBytes(N_PRECOMP_HEX)

    private const val M_PRECOMP_HEX = ""

    private const val N_PRECOMP_HEX = ""

    private fun hexToBytes(hex: String): ByteArray {
        val out = ByteArray(hex.length / 2)
        var i = 0
        while (i < out.size) {
            out[i] = hex.substring(i * 2, i * 2 + 2).toInt(16).toByte()
            i += 1
        }
        return out
    }
}
